def main():
    data = pd.read_csv(ROOT/'data/trump_policy_tweets_integrated_review.csv', dtype=str, keep_default_na=False)
    prior = pd.read_csv(ROOT/'docs/tweet_audit_2026-11-02/conservative_review_integrated_2026-11-03.csv', dtype=str, keep_default_na=False)
    current = data.merge(prior[['raw_row','review_state']],on='raw_row',validate='one_to_one')
    current = current[(current.additional_status=='include_extended') & (current.review_state=='not_reviewed_under_conservative_standard')].set_index('raw_row')
    rows=[]
    for decision,items in [('exclude_core',EXCLUDED),('hold',HOLD)]:
        for rid in items:
            s=str(rid); assert s in current.index
            text=current.loc[s,'text']
            reason=('완결된 저장 본문은 경제성과·선거·보건 또는 회의 언급이며 새로운 구체 무역·관세 발표를 제시하지 않는다. 다른 정책 보조분석은 별도.' if decision=='exclude_core' else '원문이 잘리거나 URL·연결 자료가 있어 무역 관련 정보의 포함 여부를 완전히 확인할 수 없어 보류한다.')
            rows.append({'raw_row':s,'decision':decision,'direction':'uncertain','reason_ko':reason})
    assert len(rows)==768 and len({r['raw_row'] for r in rows})==768
    pd.DataFrame(rows).to_csv(OUT,index=False,encoding='utf-8-sig')
    print('Recorded:',len(rows),'excluded:',len(EXCLUDED),'hold:',len(HOLD))

if __name__ == '__main__': main()
